int mutt_strncmp(const char *a, const char *b, size_t l) /* <=== mutt_strncmp */ 
{
  return strncmp(NONULL(a), NONULL(b), l);
}

size_t mutt_strlen(const char *a) /* <=== mutt_strlen */ 
{
  return a ? strlen (a) : 0;
}

static unsigned char decode_byte (char ch) /* <=== decode_byte */ 
{
  if (ch == 96)
    return 0;
  return ch - 32;
}

static void state_prefix_put (const char *d, size_t dlen, STATE *s) /* <=== state_prefix_put */ 
{
  if (s->prefix)
    while (dlen--)
      state_prefix_putc (*d++, s);
  else
    fwrite (d, dlen, 1, s->fpout);
}

